import calendar
from datetime import date


def nth_weekday(year, month, weekday, n):
    """Return the ISO date of the n-th `weekday` (0=Mon .. 6=Sun) in the month.

    n in 1..5 selects the first..fifth occurrence; n == -1 selects the last.
    Raises ValueError if the occurrence does not exist (or on bad arguments).
    """
    if not isinstance(weekday, int) or isinstance(weekday, bool) or not 0 <= weekday <= 6:
        raise ValueError("weekday must be an integer 0 (Monday) .. 6 (Sunday)")
    if n not in (1, 2, 3, 4, 5, -1):
        raise ValueError("n must be 1..5 or -1")

    first_weekday, days_in_month = calendar.monthrange(year, month)  # may raise ValueError

    # Day-of-month of the first occurrence of the requested weekday.
    first_occurrence = 1 + (weekday - first_weekday) % 7

    if n == -1:
        day = first_occurrence + 7 * ((days_in_month - first_occurrence) // 7)
    else:
        day = first_occurrence + 7 * (n - 1)
        if day > days_in_month:
            raise ValueError(
                "no occurrence %d of weekday %d in %04d-%02d" % (n, weekday, year, month)
            )

    return date(year, month, day).isoformat()
